&lt;ul style=&quot;margin-top:2px&quot;&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bouclier-B&#233;ni-(Paladin).html&quot; title=&quot;Bouclier b&#233;ni&quot;&gt;Bouclier b&#233;ni&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Champion-Du-Temple-(Paladin).html&quot; title=&quot;Champion du temple&quot;&gt;Champion du temple&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Champion-Temp&#233;r&#233;-(Paladin).html&quot; title=&quot;Champion temp&#233;r&#233;&quot;&gt;Champion temp&#233;r&#233;&lt;/a&gt; (&lt;i&gt;WMH&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chasseur-De-Fant&#244;mes-(Paladin).html&quot; title=&quot;Chasseur de fant&#244;mes&quot;&gt;Chasseur de fant&#244;mes&lt;/a&gt; (AO)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chasseur-Divin-(Paladin).html&quot; title=&quot;Chasseur divin&quot;&gt;Chasseur divin&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chevalier-Des-Pi&#232;ces-(Paladin).html&quot; title=&quot;Chevalier des pi&#232;ces&quot;&gt;Chevalier des pi&#232;ces&lt;/a&gt; (MM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chevalier-Empyr&#233;en-(Paladin).html&quot; title=&quot;Chevalier empyr&#233;en&quot;&gt;Chevalier empyr&#233;en&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chevalier-&#201;tincelant-(Paladin).html&quot; title=&quot;Chevalier &#233;tincelant&quot;&gt;Chevalier &#233;tincelant&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;fenseur-Divin-(Paladin).html&quot; title=&quot;D&#233;fenseur divin&quot;&gt;D&#233;fenseur divin&lt;/a&gt; (APG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Elu-(Paladin).html&quot; title=&quot;&#201;lu&quot;&gt;&#201;lu&lt;/a&gt; &lt;i&gt;(FF)&lt;/i&gt;&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;p&#233;e-Du-Courage-(Paladin).html&quot; title=&quot;&#201;p&#233;e du courage&quot;&gt;&#201;p&#233;e du courage&lt;/a&gt; (MMI)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Fl&#233;au-Des-Morts-Vivants-(Paladin).html&quot; title=&quot;Fl&#233;au des morts-vivants&quot;&gt;Fl&#233;au des morts-vivants&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Glaive-De-Lesprit-(Paladin).html&quot; title=&quot;Glaive de l&amp;#39;esprit&quot;&gt;Glaive de l&#39;esprit&lt;/a&gt; (&lt;i&gt;OO&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Guerrier-De-La-Lumi&#232;re-Sainte-(Paladin).html&quot; title=&quot;Guerrier de la lumi&#232;re sainte&quot;&gt;Guerrier de la lumi&#232;re sainte&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Guide-Saint-(Paladin).html&quot; title=&quot;Guide saint&quot;&gt;Guide saint&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Hospitalier-(Paladin).html&quot; title=&quot;Hospitalier&quot;&gt;Hospitalier&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;L&#233;gat-(Paladin).html&quot; title=&quot;L&#233;gat&quot;&gt;L&#233;gat&lt;/a&gt; (&lt;i&gt;AMH&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Paladin-Asserment&#233;-(Paladin).html&quot; title=&quot;Paladin asserment&#233;&quot;&gt;Paladin asserment&#233;&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Paladin-Gris-(Paladin).html&quot; title=&quot;Paladin gris&quot;&gt;Paladin gris&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#233;dempteur-(Paladin).html&quot; title=&quot;R&#233;dempteur&quot;&gt;R&#233;dempteur&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Demi-Orque.html&quot; title=&quot;Les demi-orques&quot;&gt;Demi-orque&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sage-Gardien-(Paladin).html&quot; title=&quot;Sage gardien&quot;&gt;Sage gardien&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Aasimar-(Race).html&quot; title=&quot;Les aasimars&quot;&gt;Aasimar&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Saint-Pistolet-(Paladin).html&quot; title=&quot;Saint pistolet&quot;&gt;Saint pistolet&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Saint-Tacticien-(Paladin).html&quot; title=&quot;Saint tacticien&quot;&gt;Saint tacticien&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Seigneur-De-Pierre-(Paladin).html&quot; title=&quot;Seigneur de pierre&quot;&gt;Seigneur de pierre&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Nain.html&quot; title=&quot;Les nains&quot;&gt;Nain&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Serviteur-Sacr&#233;-(Paladin).html&quot; title=&quot;Serviteur sacr&#233;&quot;&gt;Serviteur sacr&#233;&lt;/a&gt; (MJRA)&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Antipaladin.html&quot; title=&quot;L&amp;#39;antipaladin&quot;&gt;L&#39;antipaladin&lt;/a&gt; (classe alternative) (APG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chevalier-Du-S&#233;pulcre-(Paladin).html&quot; title=&quot;Chevalier du s&#233;pulcre&quot;&gt;Chevalier du s&#233;pulcre&lt;/a&gt; (UC)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Insinuateur-(Paladin).html&quot; title=&quot;Insinuateur&quot;&gt;Insinuateur&lt;/a&gt; &lt;i&gt;(AoE)&lt;/i&gt;&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Saccageur-(Paladin).html&quot; title=&quot;Saccageur&quot;&gt;Saccageur&lt;/a&gt; &lt;i&gt;(ISC)&lt;/i&gt;&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Semeur-De-Peur-(Antipaladin).html&quot; title=&quot;Semeur de peur&quot;&gt;Semeur de peur&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Gobelours.html&quot; title=&quot;Gobelours&quot;&gt;Gobelours&lt;/a&gt;) (CM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tyran-(Antipaladin).html&quot; title=&quot;Tyran&quot;&gt;Tyran&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tyran-De-Fer-(Antipaladin).html&quot; title=&quot;Tyran de fer&quot;&gt;Tyran de fer&lt;/a&gt; (&lt;i&gt;AMH&lt;/i&gt;)&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la guerre (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Combat/Art de la Guerre&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUC.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;i&gt;Le chevalier du s&#233;pulcre ne se contente pas de voir son &#226;me corrompue &#224; la mani&#232;re de l’antipaladin, il sacrifie sa mortalit&#233; en m&#234;me temps que sa moralit&#233;.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;Cet arch&#233;type est seulement accessible &#224; la classe alternative d’&lt;a class=&quot;pagelink&quot; href=&quot;Antipaladin.html&quot; title=&quot;L&amp;#39;antipaladin&quot;&gt;antipaladin&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Caresse de la crypte (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Caresse_de_la_crypte_Ext_0&quot; href=&quot;#Caresse_de_la_crypte_Ext_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Niveau.html&quot; title=&quot;niveau&quot;&gt;niveau&lt;/a&gt; 5, le chevalier du s&#233;pulcre gagne un bonus de +2 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;jet de sauvegarde&quot;&gt;jets de sauvegarde&lt;/a&gt; contre les effets mentaux, les effets de mort et les &lt;a class=&quot;pagelink&quot; href=&quot;Poisons.html&quot; title=&quot;poison&quot;&gt;poisons&lt;/a&gt;. L’&#233;nergie positive le blesse et l’&#233;nergie n&#233;gative le soigne comme s’il &#233;tait un mort-vivant, mais celle qui ne soigne pas les morts-vivants (comme &#233;nergie n&#233;gative) l’affecte normalement. Le chevalier du s&#233;pulcre a 25% de chances d’ignorer un &lt;a class=&quot;pagelink&quot; href=&quot;Actions-Simples#Coupcritique.html&quot; title=&quot;coup critique&quot;&gt;coup critique&lt;/a&gt; et les d&#233;g&#226;ts suppl&#233;mentaires des &lt;a class=&quot;pagelink&quot; href=&quot;Roublard.html#ATTAQUESOURNOISE&quot; title=&quot;Le roublard&quot;&gt;attaques sournoises&lt;/a&gt;, comme s’il portait une &lt;a class=&quot;pagelink&quot; href=&quot;Armures-Magiques.html#D&#233;fense&quot; title=&quot;Les armures et boucliers magiques&quot;&gt;armure de d&#233;fense l&#233;g&#232;re&lt;/a&gt;. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Antipaladin.html#FAVEURDESFIELONS&quot; title=&quot;L&amp;#39;antipaladin&quot;&gt;faveur des fi&#233;lons&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Vigueur de la crypte (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Vigueur_de_la_crypte_Ext_1&quot; href=&quot;#Vigueur_de_la_crypte_Ext_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 8, le chevalier du s&#233;pulcre est immunis&#233; contre le &lt;a class=&quot;pagelink&quot; href=&quot;Poisons.html&quot; title=&quot;poison&quot;&gt;poison&lt;/a&gt;. Il gagne aussi &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Dans-Le-Noir-(Capacit&#233;).html&quot; title=&quot;vision dans le noir&quot;&gt;vision dans le noir&lt;/a&gt; &#224; 18 m&#232;tres (12 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;) s’il ne l’avait pas d&#233;j&#224;. Ce pouvoir remplace l’&lt;a class=&quot;pagelink&quot; href=&quot;Antipaladin.html#AURADEDESESPOIR&quot; title=&quot;L&amp;#39;antipaladin&quot;&gt;aura de d&#233;sespoir&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Cape de la crypte (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Cape_de_la_crypte_Ext_2&quot; href=&quot;#Cape_de_la_crypte_Ext_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 10, le chevalier du s&#233;pulcre est immunis&#233; contre l’&lt;a class=&quot;pagelink&quot; href=&quot;Absorption-D&#233;nergie-(Capacit&#233;).html&quot; title=&quot;absorption d&amp;#39;&#233;nergie&quot;&gt;absorption d’&#233;nergie&lt;/a&gt; et les effets n&#233;fastes de l’&#233;nergie n&#233;gative. Ses chances d’ignorer un coup critique et les d&#233;g&#226;ts suppl&#233;mentaires des &lt;a class=&quot;pagelink&quot; href=&quot;Roublard.html#ATTAQUESOURNOISE&quot; title=&quot;Le roublard&quot;&gt;attaques sournoises&lt;/a&gt; passent &#224; 50%, comme s’il portait une &lt;a class=&quot;pagelink&quot; href=&quot;Armures-Magiques.html#D&#233;fense&quot; title=&quot;Les armures et boucliers magiques&quot;&gt;armure de d&#233;fense interm&#233;diaire&lt;/a&gt;. Ce pouvoir remplace le &lt;a class=&quot;pagelink&quot; href=&quot;Antipaladin.html#CHATIMENTDUBIEN&quot; title=&quot;L&amp;#39;antipaladin&quot;&gt;ch&#226;timent du Bien&lt;/a&gt; du niveau 10.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Volont&#233; de la crypte (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Volont&#233;_de_la_crypte_Ext_3&quot; href=&quot;#Volont&#233;_de_la_crypte_Ext_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 11, le bonus que le chevalier du s&#233;pulcre gagne aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;jet de sauvegarde&quot;&gt;jets de sauvegarde&lt;/a&gt; contre les effets mentaux et les effets de mort passe &#224; +4. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Antipaladin.html#AURADEVENGEANCE&quot; title=&quot;L&amp;#39;antipaladin&quot;&gt;aura de vengeance&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Armes du p&#233;ch&#233; (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Armes_du_p&#233;ch&#233;_Sur_4&quot; href=&quot;#Armes_du_p&#233;ch&#233;_Sur_4&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 14, les armes du chevalier du s&#233;pulcre sont consid&#233;r&#233;es comme Mauvaises lorsqu’il s’agit d’ignorer la &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;duction-De-D&#233;g&#226;ts-(Capacit&#233;).html&quot; title=&quot;RD&quot;&gt;RD&lt;/a&gt;. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Antipaladin.html#AURADUPECHE&quot; title=&quot;L&amp;#39;antipaladin&quot;&gt;aura du p&#233;ch&#233;&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Seigneur de la crypte (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Seigneur_de_la_crypte_Ext_5&quot; href=&quot;#Seigneur_de_la_crypte_Ext_5&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 15, le chevalier du s&#233;pulcre a 75% de chances d’ignorer un coup critique et les d&#233;g&#226;ts suppl&#233;mentaires des attaques sournoises, comme s’il portait une &lt;a class=&quot;pagelink&quot; href=&quot;Armures-Magiques.html#D&#233;fense&quot; title=&quot;Les armures et boucliers magiques&quot;&gt;armure de d&#233;fense lourde&lt;/a&gt;. Il est immunis&#233; contre les effets de mort, la &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Paralys&#233;.html&quot; title=&quot;Paralys&#233;&quot;&gt;paralysie&lt;/a&gt;, les effets de sommeil et l’&lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#&#201;tourdi.html&quot; title=&quot;&#201;tourdi&quot;&gt;&#233;tourdissement&lt;/a&gt;. Il n’a plus besoin de dormir. Il est aussi immunis&#233; contre les effets de &lt;a class=&quot;pagelink&quot; href=&quot;../&#201;tats pr&#233;judiciables#Fatigu&#233;

Un personnage fatigu&#233; est dans l’incapacit&#233; de courir et de charger/-Il-Subit-Un-Malus-De--2-En-Force-Ainsi-Qu’En-Dext&#233;rit&#233;.html&quot; title=&quot;Fatigu&#233;&quot;&gt;fatigue&lt;/a&gt; et ceux qui devraient l’&lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#&#201;puis&#233;.html&quot; title=&quot;&#201;puis&#233;&quot;&gt;&#233;puiser&lt;/a&gt; le fatiguent seulement. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Antipaladin.html#CRUAUTE&quot; title=&quot;L&amp;#39;antipaladin&quot;&gt;cruaut&#233;&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;&#194;me de la crypte (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;&#194;me_de_la_crypte_Sur_6&quot; href=&quot;#&#194;me_de_la_crypte_Sur_6&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 17, le chevalier du s&#233;pulcre gagne une &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;duction-De-D&#233;g&#226;ts-(Capacit&#233;).html&quot; title=&quot;RD&quot;&gt;RD&lt;/a&gt; 5/contondant et Bien. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Antipaladin.html#AURADEDEPRAVATION&quot; title=&quot;L&amp;#39;antipaladin&quot;&gt;aura de d&#233;pravation&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Champion non-mort (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Champion_non-mort_Ext_7&quot; href=&quot;#Champion_non-mort_Ext_7&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 20, le chevalier du s&#233;pulcre rejoint les rangs des morts-vivants. Sa &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;duction-De-D&#233;g&#226;ts-(Capacit&#233;).html&quot; title=&quot;RD&quot;&gt;RD&lt;/a&gt; passe &#224; 10/contondant et Bien. Il devient de type &lt;a class=&quot;pagelink&quot; href=&quot;Type-Mort-Vivant.html&quot; title=&quot;Mort-vivant&quot;&gt;mort-vivant&lt;/a&gt; et acquiert toutes les caract&#233;ristiques qui vont avec. Il est immunis&#233; contre les &lt;a class=&quot;pagelink&quot; href=&quot;Maladies.html&quot; title=&quot;Les maladies&quot;&gt;maladies&lt;/a&gt; mais peut de tout m&#234;me en &#234;tre porteur et les r&#233;pandre gr&#226;ce au pouvoir d’antipaladin &lt;a class=&quot;pagelink&quot; href=&quot;Antipaladin.html#VECTEURDEMALADIE&quot; title=&quot;L&amp;#39;antipaladin&quot;&gt;vecteur de maladie&lt;/a&gt;. Le champion non-mort n’a plus de valeur de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Constitution.html&quot; title=&quot;La Constitution&quot;&gt;Constitution&lt;/a&gt;. Il utilise son &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Le Charisme&quot;&gt;Charisme&lt;/a&gt; pour calculer ses &lt;a class=&quot;pagelink&quot; href=&quot;Point-De-Vie.html&quot; title=&quot;pv&quot;&gt;points de vie&lt;/a&gt;, ses jets de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Vigueur&quot;&gt;Vigueur&lt;/a&gt; et utiliser les pouvoirs sp&#233;ciaux bas&#233;s sur la Constitution. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Antipaladin.html#CHAMPIONMAUDIT&quot; title=&quot;L&amp;#39;antipaladin&quot;&gt;champion maudit&lt;/a&gt;.
